def select_demand_records(corpus_df):
    fallback_ids = ['n06-r07', 'n06-r08']
    work = corpus_df.reindex(columns=['record_id', 'need', 'demand_score', 'source_id', 'source_weight'])
    records = []
    for (_, row) in work.iterrows():
        demand_score = row.get('demand_score', 0)
        record_id = row.get('record_id', '')
        if pd.isna(demand_score):
            demand_score = 0
        if pd.isna(record_id):
            record_id = ''
        if demand_score >= 3 or record_id in fallback_ids:
            records.append({'record_id': record_id, 'need': '' if pd.isna(row.get('need', '')) else row.get('need', ''), 'demand_score': int(demand_score), 'source_id': '' if pd.isna(row.get('source_id', '')) else row.get('source_id', ''), 'source_weight': 0 if pd.isna(row.get('source_weight', 0)) else int(row.get('source_weight', 0))})
    return pd.DataFrame(records, columns=['record_id', 'need', 'demand_score', 'source_id', 'source_weight'])

def assemble_provenance(normalized_df):
    records = []
    for (_, row) in normalized_df.iterrows():
        demand_score = row.get('demand_score', 0)
        record_id = row.get('record_id', '')
        records.append({'record_id': '' if pd.isna(record_id) else record_id, 'source_id': '' if pd.isna(row.get('source_id', '')) else row.get('source_id', ''), 'source_weight': 0 if pd.isna(row.get('source_weight', 0)) else int(row.get('source_weight', 0)), 'demand_score': 0 if pd.isna(demand_score) else int(demand_score)})
    ordered = sorted(records, key=lambda item: (-item.get('demand_score', 0), item.get('record_id', '')))
    evidence_records = []
    for (rank, item) in enumerate(ordered, start=1):
        evidence_records.append({'record_id': item.get('record_id', ''), 'source_id': item.get('source_id', ''), 'source_weight': item.get('source_weight', 0), 'rank': rank})
    return pd.DataFrame(evidence_records, columns=['record_id', 'source_id', 'source_weight', 'rank'])

